import java.io.*;
import java.util.*;

public class Main {
    static int n, m;
    static int[][] grid;
    static int totalPairs;
    static int[][] pairPositions; // pairPositions[pairId][0 or 1] = index in grid
    static int[] pairOf; // pairOf[index] = pairId
    static int[] indexToPair;
    static int[][] idx; // idx[i][j] = linear index
    static int[][] pos; // pos[index] = {i, j}
    static boolean[] used;
    static int minSwaps;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        n = Integer.parseInt(parts[0]);
        m = Integer.parseInt(parts[1]);
        grid = new int[n][m];
        idx = new int[n][m];
        pos = new int[n * m][2];
        indexToPair = new int[n * m];
        pairOf = new int[n * m];
        int maxPair = (n * m) / 2;
        pairPositions = new int[maxPair + 1][2];
        for (int i = 0; i < maxPair + 1; i++) {
            pairPositions[i][0] = -1;
            pairPositions[i][1] = -1;
        }

        int linearIndex = 0;
        for (int i = 0; i < n; i++) {
            parts = br.readLine().split(" ");
            for (int j = 0; j < m; j++) {
                grid[i][j] = Integer.parseInt(parts[j]);
                idx[i][j] = linearIndex;
                pos[linearIndex][0] = i;
                pos[linearIndex][1] = j;
                int pairId = grid[i][j];
                if (pairPositions[pairId][0] == -1) {
                    pairPositions[pairId][0] = linearIndex;
                } else {
                    pairPositions[pairId][1] = linearIndex;
                }
                indexToPair[linearIndex] = pairId;
                linearIndex++;
            }
        }

        totalPairs = maxPair;
        used = new boolean[totalPairs + 1];
        minSwaps = Integer.MAX_VALUE;

        // Precompute adjacency list for each index
        List<Integer>[] adj = new ArrayList[n * m];
        for (int i = 0; i < n * m; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int cur = idx[i][j];
                if (i + 1 < n) adj[cur].add(idx[i + 1][j]);
                if (j + 1 < m) adj[cur].add(idx[i][j + 1]);
                if (i - 1 >= 0) adj[cur].add(idx[i - 1][j]);
                if (j - 1 >= 0) adj[cur].add(idx[i][j - 1]);
            }
        }

        // For each pair, compute the minimum swaps to place them adjacent
        int result = 0;
        for (int pairId = 1; pairId <= totalPairs; pairId++) {
            int a = pairPositions[pairId][0];
            int b = pairPositions[pairId][1];
            if (areAdjacent(a, b)) continue;
            // Find minimum swaps to make them adjacent
            int minDist = Integer.MAX_VALUE;
            // BFS from a to find closest cell to b that is adjacent to b
            Queue<Integer> q = new LinkedList<>();
            int[] dist = new int[n * m];
            Arrays.fill(dist, -1);
            q.add(a);
            dist[a] = 0;
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int v : adj[u]) {
                    if (dist[v] == -1) {
                        dist[v] = dist[u] + 1;
                        q.add(v);
                    }
                }
            }
            // Find minimum distance from a to any neighbor of b
            for (int v : adj[b]) {
                if (dist[v] != -1) {
                    minDist = Math.min(minDist, dist[v]);
                }
            }
            if (minDist == Integer.MAX_VALUE) {
                // Try moving b towards a
                q = new LinkedList<>();
                dist = new int[n * m];
                Arrays.fill(dist, -1);
                q.add(b);
                dist[b] = 0;
                while (!q.isEmpty()) {
                    int u = q.poll();
                    for (int v : adj[u]) {
                        if (dist[v] == -1) {
                            dist[v] = dist[u] + 1;
                            q.add(v);
                        }
                    }
                }
                for (int v : adj[a]) {
                    if (dist[v] != -1) {
                        minDist = Math.min(minDist, dist[v]);
                    }
                }
            }
            result += minDist;
        }
        System.out.println(result);
    }

    static boolean areAdjacent(int a, int b) {
        int ax = pos[a][0], ay = pos[a][1];
        int bx = pos[b][0], by = pos[b][1];
        return Math.abs(ax - bx) + Math.abs(ay - by) == 1;
    }
