    static int totalPairs;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        grid = new int[n][m];
        int maxPair = (n * m) / 2;
        pos = new int[maxPair + 1][4]; // 1-based
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = sc.nextInt();
                int p = grid[i][j];
                if (pos[p][0] == 0 && pos[p][1] == 0) {
                    pos[p][0] = i;
                    pos[p][1] = j;
                } else {
                    pos[p][2] = i;
                    pos[p][3] = j;
                }
            }
        }
        totalPairs = maxPair;
        int result = solve();
        System.out.println(result);
    }

    static int solve() {
        int[][] dist = new int[n][m];
        for (int[] row : dist) Arrays.fill(row, -1);
        Queue<int[]> q = new LinkedList<>();
        // Start from all positions of all pairs
        for (int p = 1; p <= totalPairs; p++) {
            int x1 = pos[p][0], y1 = pos[p][1];
            int x2 = pos[p][2], y2 = pos[p][3];
            if (dist[x1][y1] == -1) {
                dist[x1][y1] = 0;
                q.add(new int[]{x1, y1});
            }
            if (dist[x2][y2] == -1) {
                dist[x2][y2] = 0;
                q.add(new int[]{x2, y2});
            }
        }
        int[] dx = {0, 0, 1, -1};
        int[] dy = {1, -1, 0, 0};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int x = cur[0], y = cur[1];
            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d], ny = y + dy[d];
                if (nx >= 0 && nx < n && ny >= 0 && ny < m && dist[nx][ny] == -1) {
                    dist[nx][ny] = dist[x][y] + 1;
                    q.add(new int[]{nx, ny});
                }
            }
        }
        int maxDist = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                maxDist = Math.max(maxDist, dist[i][j]);
            }
        }
        return maxDist;
    }
}
