    static int[][] pairPos;
    static int totalPairs;
    static int[] dx = {-1, 1, 0, 0};
    static int[] dy = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        grid = new int[n][m];
        int maxPair = n * m / 2;
        pairPos = new int[maxPair + 1][4]; // [pair][0..3] = x1,y1,x2,y2
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = sc.nextInt();
            }
        }
        totalPairs = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int p = grid[i][j];
                if (pairPos[p][0] == 0 && pairPos[p][1] == 0) {
                    pairPos[p][0] = i;
                    pairPos[p][1] = j;
                } else {
                    pairPos[p][2] = i;
                    pairPos[p][3] = j;
                    totalPairs++;
                }
            }
        }
        int[][] dist = new int[n][m];
        for (int[] row : dist) Arrays.fill(row, -1);
        Queue<int[]> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (isPairComplete(i, j)) {
                    dist[i][j] = 0;
                    q.offer(new int[]{i, j});
                }
            }
        }
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int x = cur[0], y = cur[1];
            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d], ny = y + dy[d];
                if (nx >= 0 && nx < n && ny >= 0 && ny < m && dist[nx][ny] == -1) {
                    dist[nx][ny] = dist[x][y] + 1;
                    q.offer(new int[]{nx, ny});
                }
            }
        }
        int maxDist = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (dist[i][j] == -1) {
                    System.out.println(-1);
                    return;
                }
                maxDist = Math.max(maxDist, dist[i][j]);
            }
        }
        System.out.println(maxDist);
    }

    static boolean isPairComplete(int i, int j) {
        int p = grid[i][j];
        int x1 = pairPos[p][0], y1 = pairPos[p][1];
        int x2 = pairPos[p][2], y2 = pairPos[p][3];
        return (i == x1 && j == y1) || (i == x2 && j == y2);
    }
