    static int totalPairs;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        grid = new int[n][m];
        int maxPair = (n * m) / 2;
        pairPos = new int[maxPair + 1][2];
        totalPairs = maxPair;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = sc.nextInt();
                int pair = grid[i][j];
                if (pairPos[pair][0] == 0 && pairPos[pair][1] == 0) {
                    pairPos[pair][0] = i * m + j + 1; // encode position as i*m+j+1
                } else {
                    pairPos[pair][1] = i * m + j + 1;
                }
            }
        }

        // For each pair, check if they are adjacent
        int alreadyPaired = 0;
        for (int p = 1; p <= maxPair; p++) {
            int pos1 = pairPos[p][0];
            int pos2 = pairPos[p][1];
            int i1 = (pos1 - 1) / m;
            int j1 = (pos1 - 1) % m;
            int i2 = (pos2 - 1) / m;
            int j2 = (pos2 - 1) % m;
            if (Math.abs(i1 - i2) + Math.abs(j1 - j2) == 1) {
                alreadyPaired++;
            }
        }

        // The answer is totalPairs - alreadyPaired
        System.out.println(totalPairs - alreadyPaired);
    }
}
