        totalPairs = n * m / 2;
        pairX = new int[totalPairs + 1];
        pairY = new int[totalPairs + 1];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = sc.nextInt();
                pairX[grid[i][j]] = i;
                pairY[grid[i][j]] = j;
            }
        }
        dist = new int[n][m];
        match = new int[n][m];
        visited = new boolean[n * m];
        for (int i = 0; i < n; i++) {
            Arrays.fill(match[i], -1);
        }
        int result = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (match[i][j] == -1) {
                    Arrays.fill(visited, false);
                    if (bfs(i, j)) {
                        result++;
                    }
                }
            }
        }
        System.out.println(result);
    }

    static boolean bfs(int startX, int startY) {
        Queue<int[]> q = new LinkedList<>();
        q.add(new int[]{startX, startY});
        visited[startX * m + startY] = true;
        while (!q.isEmpty()) {
            int[] curr = q.poll();
            int x = curr[0], y = curr[1];
            if (match[x][y] == -1) {
                return true;
            }
            int nx = pairX[grid[x][y]];
            int ny = pairY[grid[x][y]];
            if (!visited[nx * m + ny]) {
                visited[nx * m + ny] = true;
                q.add(new int[]{nx, ny});
            }
        }
        return false;
    }
