                if (pairPositions[p][0] == 0 && pairPositions[p][1] == 0) {
                    pairPositions[p][0] = i;
                    pairPositions[p][1] = j;
                } else {
                    pairPositions[p][2] = i;
                    pairPositions[p][3] = j;
                }
            }
        }

        // BFS
        int result = bfs();
        System.out.println(result);
    }

    static int bfs() {
        int[][] start = new int[n][m];
        for (int i = 0; i < n; i++) {
            System.arraycopy(grid[i], 0, start[i], 0, m);
        }

        Queue<int[][]> queue = new LinkedList<>();
        Map<String, Integer> visited = new HashMap<>();
        String startKey = getKey(start);
        visited.put(startKey, 0);
        queue.offer(start);

        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[][] current = queue.poll();
            int steps = visited.get(getKey(current));

            if (isNeat(current)) {
                return steps;
            }

            // Find all pairs that are not adjacent
            for (int p = 1; p <= totalPairs; p++) {
                int x1 = pairPositions[p][0], y1 = pairPositions[p][1];
                int x2 = pairPositions[p][2], y2 = pairPositions[p][3];
                if (Math.abs(x1 - x2) + Math.abs(y1 - y2) != 1) {
                    // Try moving each shoe of the pair to adjacent cells
                    for (int moveIdx = 0; moveIdx < 2; moveIdx++) {
                        int cx = (moveIdx == 0) ? x1 : x2;
                        int cy = (moveIdx == 0) ? y1 : y2;
                        for (int d = 0; d < 4; d++) {
                            int nx = cx + dx[d];
                            int ny = cy + dy[d];
                            if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
                                int[][] next = copy(current);
                                // Swap the shoe at (cx,cy) with (nx,ny)
                                int temp = next[nx][ny];
                                next[nx][ny] = next[cx][cy];
                                next[cx][cy] = temp;

                                // Update pairPositions for this pair
                                if (moveIdx == 0) {
                                    pairPositions[p][0] = nx;
                                    pairPositions[p][1] = ny;
                                } else {
                                    pairPositions[p][2] = nx;
                                    pairPositions[p][3] = ny;
                                }

                                String key = getKey(next);
                                if (!visited.containsKey(key)) {
                                    visited.put(key, steps + 1);
                                    queue.offer(next);
                                }

                                // Revert pairPositions
                                if (moveIdx == 0) {
                                    pairPositions[p][0] = x1;
                                    pairPositions[p][1] = y1;
                                } else {
                                    pairPositions[p][2] = x2;
                                    pairPositions[p][3] = y2;
                                }
                            }
                        }
                    }
                }
            }
        }
        return -1;
    }

    static boolean isNeat(int[][] state) {
        for (int p = 1; p <= totalPairs; p++) {
            int x1 = pairPositions[p][0], y1 = pairPositions[p][1];
            int x2 = pairPositions[p][2], y2 = pairPositions[p][3];
            if (Math.abs(x1 - x2) + Math.abs(y1 - y2) != 1) {
                return false;
            }
        }
        return true;
    }

    static int[][] copy(int[][] src) {
        int[][] dest = new int[n][m];
        for (int i = 0; i < n; i++) {
            System.arraycopy(src[i], 0, dest[i], 0, m);
        }
        return dest;
    }

    static String getKey(int[][] state) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                sb.append(state[i][j]).append(",");
            }
        }
        return sb.toString();
    }
