            }
        }
        minSwaps = Integer.MAX_VALUE;
        solve();
        System.out.println(minSwaps);
    }

    static void solve() {
        int[][] pairPositions = new int[totalPairs + 1][4]; // 1-based indexing for pairs
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int val = grid[i][j];
                if (pairPositions[val][0] == 0) {
                    pairPositions[val][0] = i + 1;
                    pairPositions[val][1] = j + 1;
                } else {
                    pairPositions[val][2] = i + 1;
                    pairPositions[val][3] = j + 1;
                }
            }
        }

        int[][] dist = new int[n + 1][m + 1];
        for (int i = 1; i <= n; i++) {
            Arrays.fill(dist[i], Integer.MAX_VALUE);
        }
        dist[1][1] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[2] - b[2]);
        pq.offer(new int[]{1, 1, 0});

        int[][] dirs = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int x = curr[0], y = curr[1], d = curr[2];
            if (d > dist[x][y]) continue;
            for (int[] dir : dirs) {
                int nx = x + dir[0], ny = y + dir[1];
                if (nx < 1 || nx > n || ny < 1 || ny > m) continue;
                int cost = 0;
                if (grid[nx - 1][ny - 1] != grid[x - 1][y - 1]) {
                    cost = 1;
                }
                if (dist[nx][ny] > d + cost) {
                    dist[nx][ny] = d + cost;
                    pq.offer(new int[]{nx, ny, dist[nx][ny]});
                }
            }
        }

        minSwaps = dist[n][m];
