import java.util.*;

public class Main {
    static int n, m;
    static int[][] grid;
    static int[][] pos; // pos[i][0] = (x,y), pos[i][1] = (x,y)
    static int totalPairs;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        grid = new int[n][m];
        totalPairs = n * m / 2;
        pos = new int[totalPairs + 1][4]; // 1-based indexing for pairs
        for (int i = 1; i <= totalPairs; i++) {
            pos[i][0] = -1; // first occurrence not found
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int val = sc.nextInt();
                grid[i][j] = val;
                if (pos[val][0] == -1) {
                    pos[val][0] = i;
                    pos[val][1] = j;
                } else {
                    pos[val][2] = i;
                    pos[val][3] = j;
                }
            }
        }
        int[][] dist = new int[n][m];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dist[i], -1);
        }
        Queue<int[]> q = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == grid[i][j]) {
                    dist[i][j] = 0;
                    q.add(new int[]{i, j});
                }
            }
        }
        int[] dx = {0, 0, 1, -1};
        int[] dy = {1, -1, 0, 0};
        while (!q.isEmpty()) {
            int[] curr = q.poll();
            int x = curr[0], y = curr[1];
            for (int k = 0; k < 4; k++) {
                int nx = x + dx[k], ny = y + dy[k];
                if (nx >= 0 && nx < n && ny >= 0 && ny < m && dist[nx][ny] == -1) {
                    dist[nx][ny] = dist[x][y] + 1;
                    q.add(new int[]{nx, ny});
                }
            }
        }
        int res = 0;
        for (int i = 1; i <= totalPairs; i++) {
            int x1 = pos[i][0], y1 = pos[i][1];
            int x2 = pos[i][2], y2 = pos[i][3];
            if (Math.abs(x1 - x2) + Math.abs(y1 - y2) != 1) {
                res += 2;
            }
        }
        System.out.println(res);
    }
}
