import java.util.*;
import java.io.*;

public class Main {
    static int n, m;
    static int[][] grid;
    static int[][] pairPos;
    static int totalPairs;
    static int minSwaps;

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        n = fs.nextInt();
        m = fs.nextInt();
        grid = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = fs.nextInt();
            }
        }

        totalPairs = n * m / 2;
        pairPos = new int[totalPairs + 1][4]; // [pair][x1,y1,x2,y2]
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int val = grid[i][j];
                if (pairPos[val][0] == 0 && pairPos[val][1] == 0) {
                    pairPos[val][0] = i;
                    pairPos[val][1] = j;
                } else {
                    pairPos[val][2] = i;
                    pairPos[val][3] = j;
                }
            }
        }

        minSwaps = Integer.MAX_VALUE;
        solve(1, 0);
        System.out.println(minSwaps);
    }

    static void solve(int pair, int swaps) {
        if (pair > totalPairs) {
            minSwaps = Math.min(minSwaps, swaps);
            return;
        }

        if (swaps >= minSwaps) return; // pruning

        int x1 = pairPos[pair][0], y1 = pairPos[pair][1];
        int x2 = pairPos[pair][2], y2 = pairPos[pair][3];

        // Case 1: already adjacent
        if (Math.abs(x1 - x2) + Math.abs(y1 - y2) == 1) {
            solve(pair + 1, swaps);
            return;
        }

        // Try all possible adjacent positions for this pair
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // Check if (i,j) and its neighbor can hold this pair
                int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};
                for (int[] d : dirs) {
                    int ni = i + d[0], nj = j + d[1];
                    if (ni >= 0 && ni < n && nj >= 0 && nj < m) {
                        // Check if current pair can be placed at (i,j) and (ni,nj)
                        // by swapping with whatever is there
                        int val1 = grid[i][j];
                        int val2 = grid[ni][nj];

                        // Calculate cost to move current pair here
                        int cost = 0;
                        // Move first shoe of current pair to (i,j)
                        if (x1 != i || y1 != j) {
                            cost++;
                            // Swap with what's at (i,j)
                            swapPositions(pair, 0, i, j);
                        }
                        // Move second shoe of current pair to (ni,nj)
                        if (x2 != ni || y2 != nj) {
                            cost++;
                            swapPositions(pair, 1, ni, nj);
                        }

                        solve(pair + 1, swaps + cost);

                        // Undo swaps
                        if (x1 != i || y1 != j) {
                            swapPositions(pair, 0, x1, y1);
                        }
                        if (x2 != ni || y2 != nj) {
                            swapPositions(pair, 1, x2, y2);
                        }
                    }
                }
            }
        }
    }

    static void swapPositions(int pair, int which, int newX, int newY) {
        int oldX = pairPos[pair][which * 2];
        int oldY = pairPos[pair][which * 2 + 1];

        // Update grid
        int temp = grid[oldX][oldY];
        grid[oldX][oldY] = grid[newX][newY];
        grid[newX][newY] = temp;

        // Update pairPos
        pairPos[pair][which * 2] = newX;
        pairPos[pair][which * 2 + 1] = newY;

        // Update the other pair that was swapped
        int otherVal = grid[oldX][oldY];
        if (otherVal != pair) {
            if (pairPos[otherVal][0] == newX && pairPos[otherVal][1] == newY) {
                pairPos[otherVal][0] = oldX;
                pairPos[otherVal][1] = oldY;
            } else {
                pairPos[otherVal][2] = oldX;
                pairPos[otherVal][3] = oldY;
            }
        }
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() throws IOException {
            if (ptr < buflen) return true;
            ptr = 0;
            buflen = in.read(buffer);
            return buflen > 0;
        }

        private int readByte() throws IOException {
            if (ptr < buflen) return buffer[ptr++];
            throw new IOException();
        }

        public int nextInt() throws IOException {
            int c = readByte();
            while (c <= ' ') c = readByte();
            boolean minus = false;
            if (c == '-') {
                minus = true;
                c = readByte();
            }
            int res = 0;
            do {
                res = res * 10 + (c - '0');
                c = readByte();
            } while (c > ' ');
            return minus ? -res : res;
        }
    }
}
